head.script:
scwin.gPvd;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gWinTyp;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_Item);
        scwin.getParam();
        if (scwin.gMainFormCd === '70567' || scwin.gMainFormCd === '00567' ||
            scwin.gMainFormCd === '91567' || scwin.gMainFormCd === '31001' ||
            scwin.gMainFormCd === '70443' || scwin.gMainFormCd === '70016') {
            panel_Hidden.show("");
        } else {
            panel_Hidden.hide();
        }
        await scwin.readSync();
        if (scwin.gLdMktTp === "1") {
            // 유가,코넥스 : 0이하일 경우 해당
            txa_2_3.Text = '분기매출액 = 결산 - 3분기\r\n결산=[91567]감사보고서제출 당기누적금액\r\n3분기=[50003]XBRL재무제표(3분기 당기누적금액)';
            txa_2_3.color = '#15549c';
            txa_3_1.Text = '당기 3개월 매출액이 0원인 경우 "해당"으로 표시';
            txa_3_1.color = '#15549c';
        } else if (scwin.gLdMktTp === "2") {
            txa_2_3.Text = '분기매출액 = 결산 - 3분기\r\n결산=[70567]감사보고서제출 당기누적금액\r\n3분기=[50003]XBRL재무제표(3분기 당기누적금액)';
            txa_2_3.color = '#15549c';
            txa_3_1.Text = '당기 3개월 매출액이 3억 미만인 경우 "해당"으로 표시';
            txa_3_1.color = '#15549c';
        } else if (scwin.gLdMktTp === "6") {
            txa_2_3.Text = '분기매출액 = 결산 - 3분기\r\n결산=[31001]감사보고서제출 당기누적금액\r\n3분기=[50003]XBRL재무제표(3분기 당기누적금액)';
            txa_2_3.color = '#15549c';
            txa_3_1.Text = '당기 3개월 매출액이 0원인 경우 "해당"으로 표시';
            txa_3_1.color = '#15549c';
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10202.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10202.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadError
 * @description dts_Item 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10202.dts_Item_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    try {
        $c.lcd.fn_setCheckBox();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10202.dts_Item_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/DisclosureStatus.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function() {
    const pvd = scwin.getProvider();
    const Temp0 = pvd.split("&")[0];
    const Temp1 = pvd.split("&")[1];
    const Temp2 = pvd.split("&")[2];
    const Temp3 = pvd.split("&")[3];
    // alert(pvd +' / '+ Temp0  +' / '+  Temp1 +' / '+ Temp2);

    scwin.gAcptNo = Temp0.split("=")[1];
    scwin.gMainFormCd = Temp1.split("=")[1]; // 처리시 뷰=P,  조회시 뷰=R
    scwin.gWinTyp = Temp2.split("=")[1];
    scwin.gPvd = Temp3.split("=")[1];
    // alert('gPvd='+gPvd);

};

/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    const url = frame.srcUrl;
    const arr = url.split("?")[1];
    return (arr.length >= 1 ? arr : undefined);
};

/**
 * @method
 * @name getNullValue
 * @description get Null Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getNullValue = function(obj) {
    let str = obj.getValue();
    if (str === '') {
        str = 0;
    }
    return str;
};

/**
 * @method
 * @name setCheckBox
 * @description set Check Box 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBox = function() {
    if (scwin.gLdMktTp === "1" || scwin.gLdMktTp === "6") {
        // 유가,코넥스 : 0이하일 경우 해당
        if (scwin.getNullValue(edt_QTR_SALES) <= 0) {
            chk_QTR_SALES.setValue(1);
            edt_QTR_SALES.ReadOnlyForeColor = 'red';
        }
    } else if (scwin.gLdMktTp === "2") {
        // 코스닥 : 3억미만일 경우 해당
        if (scwin.getNullValue(edt_QTR_SALES) < 300000000) {
            chk_QTR_SALES.setValue(1);
            edt_QTR_SALES.ReadOnlyForeColor = 'red';
        }
    }
};
